import{_ as o,o as i,c as a,a2 as n}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"Presenza in tempo reale","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/presenza.md","filePath":"admin-guide/presenza.md"}'),s={name:"admin-guide/presenza.md"};function t(r,e,l,c,d,p){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="presenza-in-tempo-reale" tabindex="-1">Presenza in tempo reale <a class="header-anchor" href="#presenza-in-tempo-reale" aria-label="Permalink to &quot;Presenza in tempo reale&quot;">​</a></h1><p>Dalla 1.8.2 il cloud ha un canale WebSocket, <code>GET /api/v1/presence</code>, che porta gli avatar e i cursori degli altri utenti sullo stesso file dei vault <strong>condivisi</strong> (ADR-0065). È la prima connessione client→cloud in tempo reale: va tenuta in conto nel proxy. Per l&#39;utente: <a href="./../user-guide/presenza.html">Presenza</a>.</p><h2 id="il-flag-features-presence" tabindex="-1">Il flag <code>features.presence</code> <a class="header-anchor" href="#il-flag-features-presence" aria-label="Permalink to &quot;Il flag \`features.presence\`&quot;">​</a></h2><ul><li>Chiave del Config Profile, <strong>acceso di default</strong>, nessun blocco (<code>locked_keys</code> non ha effetto). Tabella delle chiavi: <a href="./profili-quote-audit.html">Profili, quote, audit</a>.</li><li>Spento, il client non apre la connessione e il cloud, se la riceve, risponde <code>presence-disabled</code> e la chiude (close code 4403). Vale <strong>a caldo</strong>: le connessioni aperte si chiudono entro pochi istanti dalla modifica del profilo (e comunque entro 60 s, il ricontrollo periodico) e gli avatar spariscono dai client.</li><li>I vault privati non hanno presenza in nessun caso.</li><li>Nessuna variabile d&#39;ambiente nuova: non c&#39;è nulla da configurare oltre al proxy.</li></ul><h2 id="proxy-e-ingress" tabindex="-1">Proxy e Ingress <a class="header-anchor" href="#proxy-e-ingress" aria-label="Permalink to &quot;Proxy e Ingress&quot;">​</a></h2><p>La rotta <code>/api/v1/presence</code> non richiede header <code>Authorization</code> (il browser non può inviarli su un WebSocket): il primo frame porta il token e il cloud lo verifica come per le altre API. Il proxy deve:</p><ol><li>lasciar passare l&#39;<strong>upgrade WebSocket</strong> (<code>Connection: Upgrade</code>, <code>Upgrade: websocket</code>);</li><li><strong>non chiudere le connessioni inattive</strong> prima del ping del server (ogni 30 s); per prudenza almeno <strong>un&#39;ora</strong> di timeout di lettura e scrittura;</li><li>non applicare alla rotta limiti di durata della richiesta.</li></ol><p><strong>Helm.</strong> Il chart crea un Ingress dedicato, <code>&lt;release&gt;-presence</code>, con path esatto <code>/api/v1/presence</code> sull&#39;host principale (<code>ingress.host</code>), che vince su <code>/</code>. I timeout di nginx (<code>proxy-read-timeout</code>, <code>proxy-send-timeout</code>) vengono da <code>ingress.presence.timeoutSeconds</code> (predefinito <strong>3600</strong>: tenetelo a 3600 o più). Con un altro controller mettete l&#39;equivalente in <code>ingress.presence.annotations</code>, che si applicano solo a questo Ingress (le <code>ingress.annotations</code> comuni si applicano a tutti). Se <code>ingress.enabled</code> è <code>false</code>, il chart non crea nulla e la configurazione è del vostro proxy.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ingress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  presence</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    timeoutSeconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    annotations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span></code></pre></div><p><strong>Docker Compose.</strong> Il <code>Caddyfile</code> di <code>deploy/compose</code> non richiede modifiche: Caddy aggiorna la connessione da solo e non ha un timeout di inattività. Se Caddy è dietro un altro proxy, valgono i punti sopra per quest&#39;ultimo.</p><p><strong>Origine.</strong> Un browser può aprire la connessione solo dalla stessa origine del cloud (la Web UI incorporata); in sviluppo è ammessa anche l&#39;origine di <code>WEB_UI_ORIGIN</code>. Il desktop non invia <code>Origin</code> ed è sempre accettato. Un proxy che riscrive l&#39;<code>Host</code> può far fallire il controllo dell&#39;origine: inoltrate l&#39;<code>Host</code> originale.</p><p><strong>CSP.</strong> La Web UI usa <code>connect-src &#39;self&#39;</code>: nei browser attuali <code>&#39;self&#39;</code> copre <code>wss:</code> sulla stessa origine. Per Safari la corrispondenza è storicamente diversa: da Safari 15.4 va verificata sul campo (runbook <a href="./../qa/m25-presenza.html"><code>docs/qa/m25-presenza.md</code></a>); se la console segnala un blocco CSP, la <code>connect-src</code> della Web UI dovrebbe nominare <code>wss://&lt;host&gt;</code> in modo esplicito (modifica del servizio, non una configurazione).</p><h2 id="scala-e-limiti" tabindex="-1">Scala e limiti <a class="header-anchor" href="#scala-e-limiti" aria-label="Permalink to &quot;Scala e limiti&quot;">​</a></h2><ul><li><strong>Solo memoria.</strong> Le stanze vivono nella RAM della replica che tiene le connessioni; non c&#39;è tabella, cache esterna né Redis. Ogni membro costa poche centinaia di byte (identità e ultima posizione, al più 256 B). Un riavvio della replica azzera le sue stanze: i client si riconnettono da soli con attesa crescente.</li><li><strong>Limiti per connessione.</strong> 16 stanze, 40 movimenti al secondo (oltre, l&#39;ultima posizione è trattenuta e inviata appena possibile), frame fino a 1 KiB (8 KiB per il frame <code>auth</code>).</li><li><strong>Limite per utente e per replica.</strong> Al più <strong>32 connessioni per utente su ogni replica</strong>; oltre, il server chiude con 1013 e il client riprova più tardi. Con N repliche il tetto effettivo è 32·N: il limite non è condiviso.</li><li><strong>Più repliche.</strong> Si parlano sul canale PostgreSQL <code>presence</code> (<code>LISTEN/NOTIFY</code>, lo stesso database del servizio, <strong>senza pooler in modalità transaction</strong>). Gli ingressi e le uscite dalle stanze arrivano a tutte le repliche; i movimenti solo se la stanza ha membri altrove, al più circa 15 al secondo. Ogni replica ripete i propri membri ogni <strong>20 s</strong> (mai scartato: coda fino a 100000 messaggi) e un membro che nessuno rinnova scade dopo <strong>70 s</strong>: se una replica muore, i suoi avatar spariscono dagli altri entro 70 s. Quando una replica riprende ad ascoltare chiede alle altre di annunciarsi.</li><li><strong>Heartbeat.</strong> Il server manda un ping ogni 30 s e chiude la connessione se il pong non arriva entro 20 s.</li><li><strong>Permessi.</strong> Si ricontrollano a ogni modifica delle condivisioni, sospensione o cambio di profilo, e ogni 60 s; i commit su un vault (per esempio uno spostamento di file fuori dallo scope di una share) fanno ricontrollare le sue stanze al più ogni 5 s per sessione, quindi chi esce dallo scope è espulso in circa 5 s. Una revoca toglie l&#39;utente dalla stanza di quel file senza chiudere la connessione; una sospensione la chiude (4403).</li><li><strong>Spegnimento ordinato.</strong> Con il drain del servizio le connessioni si chiudono con «going away» e i client si riconnettono su un&#39;altra replica.</li><li><strong>Monitoraggio.</strong> Per decisione dell&#39;owner la 1.8.2 non ha metriche Prometheus dedicate alla presenza. I log in <code>debug</code> contano aperture e chiusure; non c&#39;è un log per ogni frame né per le posizioni.</li></ul><h2 id="problemi-comuni" tabindex="-1">Problemi comuni <a class="header-anchor" href="#problemi-comuni" aria-label="Permalink to &quot;Problemi comuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sintomo</th><th>Causa probabile</th><th>Rimedio</th></tr></thead><tbody><tr><td>Gli avatar compaiono e spariscono ogni minuto circa</td><td>Il proxy chiude le connessioni inattive (60 s di default)</td><td>Alzare i timeout (<code>ingress.presence.timeoutSeconds</code>)</td></tr><tr><td>Nessuno vede nessuno</td><td>Upgrade WebSocket bloccato dal proxy, o <code>features.presence</code> spento</td><td>Verificare l&#39;upgrade e il profilo effettivo dell&#39;utente</td></tr><tr><td>Gli avatar di un utente restano fino a 70 s dopo la chiusura</td><td>La replica che lo serviva è caduta</td><td>Atteso: scadono con il TTL</td></tr><tr><td>Il browser non si collega, il desktop sì</td><td>Origine non ammessa o CSP</td><td>Vedere «Origine» e «CSP» sopra</td></tr></tbody></table>`,16)])])}const h=o(s,[["render",t]]);export{g as __pageData,h as default};
